RRB.load({"id":"ntpc-2025-aug-28-s2","exam":"ntpc","label":"NTPC UG CBT 1 · 28 Aug 2025 · Shift 2","time":"12:45 PM - 2:15 PM","dropped":0,"questions":[{"s":"General Awareness","q":"Who among the following was the runner-up defeated by Viktor Axelsen in his third India Open victory in the 2025 India Open Badminton Tournament in January 2025?","o":["Anthony Sinisuka Ginting","Lakshay Sen","Lee Cheuk Yiu","Chou Tien Chen"],"a":2,"e":"Viktor Axelsen beat Lee Cheuk Yiu of Hong Kong in the 2025 India Open final for his third India Open title.","qh":"जनवरी 2025 में, आयोजित वर्ष 2025 इंडिया ओपन बैडमिंटन टूर्नामेंट में विक्टर एक्सेलसेन द्वारा अपनी तीसरी इंडिया ओपन जीत में पराजित उपविजेता कौन था?","oh":["एंथनी सिनिसुका गिंटिंग (Anthony Sinisuka Ginting)","लक्ष्य सेन (Lakshay Sen)","ली चेउक यिउ (Lee Cheuk Yiu)","चाउ टीएन चेन (Chou Tien Chen)"],"eh":"विक्टर एक्सेलसेन ने 2025 इंडिया ओपन फाइनल में हांगकांग के ली चेउक यिउ को हराकर अपना तीसरा इंडिया ओपन खिताब जीता।"},{"s":"General Awareness","q":"In which of the following years was Delhi Metro Rail Corporation established?","o":["1992","1995","1999","1997"],"a":1,"e":"Delhi Metro Rail Corporation (DMRC) was set up in 1995.","qh":"दिल्ली मेट्रो रेल कॉपोंरेशन की स्थापना निम्नलिखित में से किस वर्ष हुई थी?","oh":["1992","1995","1999","1997"],"eh":"दिल्ली मेट्रो रेल कॉर्पोरेशन (DMRC) की स्थापना 1995 में हुई।"},{"s":"General Awareness","q":"What is the full name of MNREGA in the Indian policy context?","o":["Modern National Rural Employment Growth Act","Mahatma Gandhi National Rural Employment Guarantee Act","Ministry for National Rural Employment Growth Agenda","Mainstream National Rural Education Guarantee Act"],"a":1,"e":"MGNREGA is the Mahatma Gandhi National Rural Employment Guarantee Act (2005).","qh":"भारतीय नीति के संदर्भ में, MNREGA का पूर्ण रूप क्या है?","oh":["Modern National Rural Employment Growth Act (मॉडर्न नेशनल रूरल इंम्प्लायमेंट ग्रोथ एक्ट)","Mahatma Gandhi National Rural Employment Guarantee Act (महात्मा गांधी नेशनल रूरल इंम्प्लायमेंट गारंटी एक्ट)","Ministry for National Rural Employment Growth Agenda (मिनिस्ट्री फॉर नेशनल रूरल इंम्प्लायमेंट ग्रोथ एजेंडा)","Mainstream National Rural Education Guarantee Act (मेनस्ट्रीम नेशनल रूरल एजुकेशन गारंटी एक्ट)"],"eh":"MGNREGA, महात्मा गांधी राष्ट्रीय ग्रामीण रोजगार गारंटी अधिनियम (2005) है।"},{"s":"General Awareness","q":"Which of the following constitutional mechanisms ensures political representation for Scheduled Castes and Scheduled Tribes in the Indian Parliament?","o":["Article 15 and 16","Article 341 and 342","Article 330 and 332","Article 338 and 339"],"a":2,"e":"Article 330 reserves Lok Sabha seats and Article 332 reserves State Assembly seats for SCs and STs.","qh":"निम्नलिखित में से कौन-सा संवैधानिक तंत्र, भारतीय संसद में अनुसूचित जातियों और अनुसूचित जनजातियों के लिए राजनीतिक प्रतिनिधित्व सुनिश्चित करता है?","oh":["अनुच्छेद 15 और 16","अनुच्छेद 341 और 342","अनुच्छेद 330 और 332","अनुच्छेद 338 और 339"],"eh":"अनुच्छेद 330 लोकसभा में और अनुच्छेद 332 राज्य विधानसभाओं में SC और ST के लिए सीटें आरक्षित करता है।"},{"s":"General Awareness","q":"The DBT‑funded project that first produced a GMP‑grade viral vector for Indian CAR‑T research was supported under which flagship scheme?","o":["Biotechnology Ignition Grant","PACE","National Biopharma Mission","Atal Jai Anusandhan"],"a":2,"e":"The CAR-T viral vector work was supported under DBT–BIRAC's National Biopharma Mission.","qh":"DBT-वित्त पोषित परियोजना, जिसने पहली बार भारतीय CAR‑T अनुसंधान के लिए GMP-ग्रेड वायरल वेक्टर (GMP‑grade viral vector) का उत्पादन किया था, किस प्रमुख योजना के तहत समर्थित थी?","oh":["जैव प्रौद्योगिकी इग्निशन अनुदान","PACE","राष्ट्रीय बायोफार्मा मिशन","अटल जय अनुसंधान"],"eh":"CAR-T वायरल वेक्टर कार्य को DBT–BIRAC के राष्ट्रीय बायोफार्मा मिशन के तहत समर्थन मिला।"},{"s":"General Awareness","q":"Which of the following rivers flows through a small part of the Great Indian Desert?","o":["Ravi","Mahanadi","Satluj","Luni"],"a":3,"e":"The Luni flows through part of the Thar (Great Indian) Desert and ends in the Rann of Kutch.","qh":"निम्नलिखित में से कौन-सी नदी, थार मरुस्थल (the Great Indian Desert) के एक छोटे से हिस्से से होकर बहती है?","oh":["रावी","महानदी","सतलुज","लूणी"],"eh":"लूनी नदी थार (महान भारतीय) मरुस्थल के एक भाग से बहती है और कच्छ के रण में समाप्त होती है।"},{"s":"General Awareness","q":"In which of the following years did Vasco da Gama land in Calicut on the Malabar Coast for the second time?","o":["1509","1502","1505","1511"],"a":1,"e":"Vasco da Gama first reached Calicut in 1498 and came back in 1502.","qh":"वास्को डी गामा निम्नलिखित में से किस वर्ष दूसरी बार मालाबार तट पर कालीकट में उतरा था?","oh":["1509","1502","1505","1511"],"eh":"वास्को द गामा पहली बार 1498 में कालीकट पहुँचा और 1502 में फिर आया।"},{"s":"General Awareness","q":"The Pochampad Dam is also known as _____________.","o":["Hirakud Project","Sri Rama Sagar Project","Bhakra Nangal Project","Nagarjuna Sagar Project"],"a":1,"e":"Pochampad Dam on the Godavari is also called the Sriram Sagar Project.","qh":"पोचमपाड (Pochampad) बांध को _____________ के नाम से भी जाना जाता है।","oh":["हीराकुंड परियोजना","श्री राम सागर परियोजना","भाखड़ा नांगल परियोजना","नागार्जुन सागर परियोजना"],"eh":"गोदावरी पर स्थित पोचमपाड बाँध को श्रीराम सागर परियोजना भी कहा जाता है।"},{"s":"General Awareness","q":"Which of the following Bengali writers composed the famous novel Anandamath?","o":["Sarat Chandra Chattopadhyay","Rabindranath Tagore","Kazi Nazrul Islam","Bankim Chandra Chattopadhyay"],"a":3,"e":"Bankim Chandra Chattopadhyay wrote Anandamath (1882), the source of 'Vande Mataram'.","qh":"प्रसिद्ध उपन्यास आनंदमठ की रचना निम्नलिखित में से किस बंगाली लेखक ने की थी?","oh":["शरत चंद्र चट्टोपाध्याय","रवींद्रनाथ टैगोर","काज़ी नज़रुल इस्लाम","बंकिम चंद्र चट्टोपाध्याय"],"eh":"बंकिम चंद्र चट्टोपाध्याय ने आनंदमठ (1882) लिखा, जिससे 'वंदे मातरम्' लिया गया है।"},{"s":"General Awareness","q":"At what age did Gautama Buddha attain Enlightenment (Nirvana) at Bodh Gaya in Bihar?","o":["49 years","42 years","35 years","29 years"],"a":2,"e":"Buddha attained enlightenment at Bodh Gaya at about 35.","qh":"गौतम बुद्ध को बिहार के बोधगया में ज्ञान (निर्वाण) की प्राप्ति किस आयु में हुई थी?","oh":["49 वर्ष","42 वर्ष","35 वर्ष","29 वर्ष"],"eh":"बुद्ध को लगभग 35 वर्ष की आयु में बोधगया में ज्ञान प्राप्त हुआ।"},{"s":"General Awareness","q":"After a hundred years of conquest and administration, the English East India Company faced a massive uprising that took place in _________.","o":["1856","1857","1854","1855"],"a":1,"e":"The Revolt of 1857 came roughly 100 years after Plassey (1757).","qh":"सौ वर्षों की विजय और प्रशासन के बाद, अंग्रेजी ईस्ट इंडिया कंपनी को _________ में एक बड़े विद्रोह का सामना करना पड़ा था।","oh":["1856","1857","1854","1855"],"eh":"1857 का विद्रोह प्लासी (1757) के लगभग 100 वर्ष बाद हुआ।"},{"s":"General Awareness","q":"How many facial bones are there in the face skeleton, each with its own anatomical landmarks and stage of development?","o":["14","18","11","21"],"a":0,"e":"The human face skeleton has 14 facial bones.","qh":"आनन कंकाल (face skeleton) में कितनी अस्थियां होती हैं, जिनमें से प्रत्येक के अपने शारीरीय लैंडमार्क (anatomical landmarks) और विकास के चरण होते हैं?","oh":["14","18","11","21"],"eh":"मानव चेहरे के कंकाल में 14 चेहरे की अस्थियाँ होती हैं।"},{"s":"General Awareness","q":"What was the theme for National Safety Day, observed on 4 March 2025?","o":["Safety & Well-being Crucial for Viksit Bharat","Safety Awareness: A National Priority","Safety First: Every Day","Secure India: Secure Future"],"a":0,"e":"The National Safety Day 2025 theme was 'Safety & Well-being Crucial for Viksit Bharat'.","qh":"4 मार्च 2025 को मनाए गए राष्ट्रीय सुरक्षा दिवस (National Safety Day) की थीम क्या थी?","eh":"राष्ट्रीय सुरक्षा दिवस 2025 का विषय था 'विकसित भारत के लिए सुरक्षा और कल्याण महत्वपूर्ण'।"},{"s":"General Awareness","q":"In the first phase of the Green Revolution (approximately mid 1960s upto mid 1970s), the use of HYV seeds was restricted to the more affluent states such as _________.","o":["Rajasthan, Gujarat and Kerala","Bihar, Odisha and West Bengal","Maharashtra, Uttar Pradesh and Assam","Punjab, Andhra Pradesh and Tamil Nadu"],"a":3,"e":"In the first phase, HYV seeds were mostly used in Punjab, Andhra Pradesh and Tamil Nadu.","qh":"हरित क्रांति के प्रथम चरण (लगभग 1960 के दशक के मध्य से 1970 के दशक के मध्य तक) में, HYV बीजों का उपयोग ___________________ जैसे अधिक समृद्ध राज्यों तक ही सीमित था।","oh":["राजस्थान, गुजरात और केरल","बिहार, ओडिशा और पश्चिम बंगाल","महाराष्ट्र, उत्तर प्रदेश और असम","पंजाब, आंध्र प्रदेश और तमिलनाडु"],"eh":"पहले चरण में HYV बीज अधिकतर पंजाब, आंध्र प्रदेश और तमिलनाडु में उपयोग किए गए।"},{"s":"General Awareness","q":"During the Later Vedic period, which of the following animals was specifically mentioned as useful for ploughing swampy land?","o":["Cow","Buffalo","Horse","Elephant"],"a":1,"e":"Later Vedic texts mention buffaloes for ploughing swampy land.","qh":"उत्तर वैदिक काल के दौरान, निम्नलिखित में से किस पशु को दलदली भूमि की जुताई हेतु विशेष रूप से उपयोगी बताया गया था?","eh":"उत्तर वैदिक ग्रंथों में दलदली भूमि की जुताई के लिए भैंसों का उल्लेख है।"},{"s":"General Awareness","q":"According to the Climate Risk Index 2025, what is India's long-term rank (1993–2022) among the most affected countries by extreme weather events?","o":["12th","9th","3rd","6th"],"a":3,"e":"Germanwatch's CRI 2025 ranked India 6th for 1993–2022.","qh":"जलवायु जोखिम सूचकांक 2025 के अनुसार, चरम मौसम की घटनाओं से सबसे अधिक प्रभावित देशों में भारत का दीर्घकालिक स्थान (1993-2022) कौन-सा है?","eh":"जर्मनवॉच के CRI 2025 ने 1993–2022 के लिए भारत को छठा स्थान दिया।"},{"s":"General Awareness","q":"Andhra Pradesh was formed in 1953 by separating Telugu-speaking areas from which of the following states?","o":["Madras","Kerala","Karnataka","Tamil Nadu"],"a":0,"e":"Andhra State was carved out of Madras State in 1953.","qh":"निम्नलिखित में से किस राज्य से तेलुगु भाषी क्षेत्रों को अलग करके 1953 में आंध्र प्रदेश का गठन किया गया था?","oh":["मद्रास","केरल","कर्नाटक","तमिलनाडु"],"eh":"आंध्र राज्य 1953 में मद्रास राज्य से अलग करके बनाया गया।"},{"s":"General Awareness","q":"The Koyna Project is constructed on a tributary of the River Krishna in which state?","o":["Karnataka","Tamil Nadu","Maharashtra","Andhra Pradesh"],"a":2,"e":"The Koyna Dam is on the Koyna, a Krishna tributary, in Maharashtra.","qh":"कोयना परियोजना किस राज्य में कृष्णा नदी की सहायक नदी पर बनाई गई है?","oh":["कर्नाटक","तमिलनाडु","महाराष्ट्र","आंध्र प्रदेश"],"eh":"कोयना बाँध महाराष्ट्र में कृष्णा की सहायक नदी कोयना पर है।"},{"s":"General Awareness","q":"Which advanced radar systems are being deployed under a ₹5,700-crore contract signed in March 2024 and operational from April 2025 to strengthen India's air defence network?","o":["Over-the-horizon radars","Synthetic aperture radars","Passive electronically scanned array radars","High-Power Radars (HPR)"],"a":3,"e":"The ₹5,700 crore contract (March 2024) was for High-Power Radars for the IAF.","qh":"भारत के वायु रक्षा नेटवर्क को मजबूत करने के लिए मार्च 2024 में हस्ताक्षरित और अप्रैल 2025 से परिचालित ₹5,700 करोड़ के अनुबंध के अंतर्गत कौन-सी उन्नत रडार प्रणालियाँ तैनात की जा रही हैं?","oh":["ओवर-द-हॉरिजन रडार (Over-the-horizon radars)","सिंथेटिक-एपर्चर रडार (Synthetic aperture radars)","पैसिव इलेक्ट्रॉनिकली स्कैन्ड एरे रडार (Passive electronically scanned array radars)","हाई-पावर रडार (High-Power Radars-HPR)"],"eh":"₹5,700 करोड़ का अनुबंध (मार्च 2024) भारतीय वायु सेना के लिए हाई-पावर रडार के लिए था।"},{"s":"General Awareness","q":"Which Fundamental Right was removed from the Indian Constitution by the 44th Amendment Act, 1978?","o":["Right to Property","Right to Freedom","Right to Education","Right to Equality"],"a":0,"e":"The 44th Amendment (1978) removed the Right to Property from Fundamental Rights. It is now Article 300A.","qh":"वें 44 संशोधन अधिनियम, 1978 द्वारा भारतीय संविधान से कौन-सा मौलिक अधिकार हटा दिया गया था?","eh":"44वें संशोधन (1978) ने संपत्ति के अधिकार को मौलिक अधिकारों से हटा दिया। अब यह अनुच्छेद 300A में है।"},{"s":"General Awareness","q":"Who is the Governor of the Reserve Bank of India as of May 2025?","o":["Shaktikanta Das","Sanjay Malhotra","Raghuram Rajan","Urjit Patel"],"a":1,"e":"Sanjay Malhotra became RBI Governor in December 2024.","qh":"मई 2025 तक की स्थिति के अनुसार, भारतीय रिजर्व बैंक के गवर्नर कौन हैं?","oh":["शक्तिकांत दास","संजय मल्होत्रा","रघुराम राजन","उर्जित पटेल"],"eh":"संजय मल्होत्रा दिसंबर 2024 में RBI गवर्नर बने।"},{"s":"General Awareness","q":"The UK–India Free Trade Agreement that concluded on 6 May 2025, primarily aims to reduce barriers to which sector listed first in its conclusion summary?","o":["Agricultural commodities","Medicinal products","Digital trade and e‑commerce","Legal services"],"a":2,"e":"The UK–India FTA conclusion summary listed digital trade first among its key areas.","qh":"6 मई 2025 को संपन्न हुए यूके-भारत मुक्त व्यापार समझौते का मुख्य उद्देश्य किस क्षेत्र में आने वाली बाधाओं को कम करना है, जिन्हें इसके निष्कर्ष सारांश में सबसे पहले सूचीबद्ध किया गया है?","eh":"UK–भारत FTA के निष्कर्ष सारांश में प्रमुख क्षेत्रों में डिजिटल व्यापार को पहले स्थान पर रखा गया।"},{"s":"General Awareness","q":"Which of the following is the correct method to rename a file or folder using the left mouse button?","o":["Click and drag the file → Rename it in the pop-up window","Double-click the file name → Type the new name → Press Esc","Select the file → Press F2 or click once on the name → Type new name → Press Enter","Select the file → Press F1 → Type new name → Press Enter"],"a":2,"e":"To rename: select the file, press F2 (or click its name once), type the new name and press Enter.","qh":"बाएं माउस बटन का उपयोग करके किसी फ़ाइल या फ़ोल्डर का नाम बदलने के लिए निम्नलिखित में से कौन-सी सही विधि है?","oh":["Click करना और फाइल ड्रैग करना → इसे पॉप-अप विंडो में रिनेम करना","फाइल नाम पर Double-click करना → नया नाम टाइप करना → Esc दबाना","फाइल सलेक्ट करना → F2 दबाना या नाम पर एक बार click करना → नया नाम टाइप करना → Enter दबाना","फाइल सलेक्ट करना → F1 दबाना → नया नाम टाइप करना → Enter दबाना"],"eh":"नाम बदलने के लिए: फ़ाइल चुनें, F2 दबाएँ (या उसके नाम पर एक बार क्लिक करें), नया नाम टाइप करें और Enter दबाएँ।"},{"s":"General Awareness","q":"In which event, at The Ten 2025 athletics meet in San Juan Capistrano, USA, did Gulveer Singh break his own national record in March 2025?","o":["Marathon","5,000m race","3,000m steeplechase","10,000m race"],"a":3,"e":"Gulveer Singh set a 10,000m national record (27:00.22) at The Ten in March 2025.","qh":"मार्च 2025 में, सैन जुआन कैपिस्ट्रानो (San Juan Capistrano), USA में द टेन 2025 (The Ten 2025) एथलेटिक्स मीट में, गुलवीर सिंह ने किस स्पर्धा में अपना ही राष्ट्रीय रिकॉर्ड तोड़ दिया?","oh":["मैराथन","5,000m दौड़","3,000m स्टीपलचेज़","10,000m दौड़"],"eh":"गुलवीर सिंह ने मार्च 2025 में 'द टेन' में 10,000m का राष्ट्रीय रिकॉर्ड (27:00.22) बनाया।"},{"s":"General Awareness","q":"Which theory suggests that planets were formed out of a cloud of material surrounding a young Sun?","o":["Collision Theory","Binary Star Hypothesis","Nebular Hypothesis","Big Bang Theory"],"a":2,"e":"The nebular hypothesis (Kant–Laplace) says planets formed from the gas and dust cloud around the young Sun.","qh":"किस सिद्धांत के अनुसार, ग्रहों का निर्माण सूर्य की युवा अवस्था के चारों ओर मौजूद पदार्थों के बादल से हुआ है?","eh":"नीहारिका परिकल्पना (कांट–लाप्लास) कहती है कि ग्रह नवजात सूर्य के चारों ओर गैस और धूल के बादल से बने।"},{"s":"General Awareness","q":"Which of the following statements about the Right to Property in India is correct?","o":["It is a fundamental right under Article 31 (now omitted).","It was completely abolished by the Forty-Second Amendment (1976).","It is a fundamental right under Article 32 of the Constitution.","It is no longer a fundamental right."],"a":3,"e":"After the 44th Amendment, property is only a constitutional/legal right (Article 300A), not a fundamental right.","qh":"भारत में संपत्ति के अधिकार के संबंध में निम्नलिखित में से कौन-सा कथन सही है?","oh":["यह अनुच्छेद 31 (अब हटा दिया गया) के अंतर्गत एक मौलिक अधिकार है।","बयालीसवें संशोधन (1976) द्वारा इसे पूरी तरह समाप्त कर दिया गया।","यह संविधान के अनुच्छेद 32 के अंतर्गत एक मौलिक अधिकार है।","यह अब मौलिक अधिकार नहीं रहा।"],"eh":"44वें संशोधन के बाद संपत्ति केवल एक संवैधानिक/कानूनी अधिकार (अनुच्छेद 300A) है, मौलिक अधिकार नहीं।"},{"s":"General Awareness","q":"In 2025, who launched 'Srjanam', India's first indigenous automated bio medical waste treatment plant?","o":["HD Kumaraswamy","Dr. Jitendra Singh","Nitin Jairam Gadkari","Manohar Lal"],"a":1,"e":"Dr. Jitendra Singh launched 'Srjanam', the CSIR-developed biomedical waste treatment unit.","qh":"2025 में, भारत के प्रथम स्वदेशी स्वचालित जैव-चिकित्सा अपशिष्ट उपचार संयंत्र 'सृजनम (Srjanam)' का शुभारंभ किसने किया था?","oh":["एच. डी. कुमारस्वामी","डॉ. जितेंद्र सिंह","नितिन जयराम गडकरी","मनोहर लाल"],"eh":"डॉ. जितेंद्र सिंह ने CSIR द्वारा विकसित जैव-चिकित्सा अपशिष्ट उपचार इकाई 'सृजनम' का शुभारंभ किया।"},{"s":"General Awareness","q":"The first human gene therapy experiment, which began in September 1990, used a retroviral vector against which deficiency?","o":["X-Linked Adrenoleukodystrophy","Mitochondrial encephalopathy","3-Methylglutaconic Aciduria","Adenosine deaminase"],"a":3,"e":"The first approved gene therapy trial (1990, Ashanti DeSilva) treated adenosine deaminase (ADA) deficiency.","qh":"प्रथम मानव जीन थेरेपी प्रयोग, जो सितम्बर 1990 में शुरू हुआ, में किस अपूर्णता के विरुद्ध रेट्रोवायरल वेक्टर (retroviral vector) का प्रयोग किया गया?","oh":["X-लिंक्ड एड्रेनोल्यूकोडिस्ट्रॉफी (X-Linked Adrenoleukodystrophy)","माइटोकॉन्ड्रियल एन्सेफैलोपैथी (Mitochondrial encephalopathy)","3-मिथाइलग्लूटाकोनिक एसिड्यूरिया (3-Methylglutaconic Aciduria )","ऐडेनोसिन डीएमीनेज (Adenosine deaminase)"],"eh":"पहला स्वीकृत जीन थेरेपी परीक्षण (1990, अशांति डिसिल्वा) एडेनोसिन डीएमिनेज़ (ADA) की कमी के उपचार के लिए था।"},{"s":"General Awareness","q":"In which year was the 2030 Agenda for Sustainable Development adopted by the United Nations Member States?","o":["2017","2015","2016","2014"],"a":1,"e":"UN members adopted the 2030 Agenda (the SDGs) in September 2015.","qh":"संयुक्त राष्ट्र के सदस्य देशों द्वारा सतत विकास के लिए 2030 एजेंडा किस वर्ष अपनाया गया था?","oh":["2017","2015","2016","2014"],"eh":"संयुक्त राष्ट्र के सदस्यों ने सितंबर 2015 में एजेंडा 2030 (SDG) को अपनाया।"},{"s":"General Awareness","q":"As of December 2024, what is the age eligibility of player to avail facility of Retired Sportsperson Empowerment Training (RESET) Programme?","o":["18-40 years","20-45 years","20-50 years","25-55 years"],"a":2,"e":"The RESET programme is for retired sportspersons aged 20–50.","qh":"दिसंबर 2024 तक की स्थिति के अनुसार, सेवानिवृत्त खिलाड़ी सशक्तिकरण प्रशिक्षण (RESET) कार्यक्रम की सुविधा का लाभ उठाने के लिए खिलाड़ी की आयु पात्रता कितनी है?","oh":["18-40 वर्ष","20-45 वर्ष","20-50 वर्ष","25-55 वर्ष"],"eh":"RESET कार्यक्रम 20–50 वर्ष के सेवानिवृत्त खिलाड़ियों के लिए है।"},{"s":"General Awareness","q":"For a spontaneous process at constant temperature and pressure, the Gibbs free energy change is ________.","o":["∆G = 0","∆G > 0","∆G < 0","∆G = ∆H + T∆S"],"a":2,"e":"For a spontaneous process at constant T and P, ΔG < 0.","qh":"स्थिर तापमान और दाब पर एक स्वतःस्फूर्त प्रक्रिया के लिए, गिब्स मुक्त ऊर्जा परिवर्तन ________ है।","eh":"स्थिर T और P पर स्वतः प्रवर्तित प्रक्रम के लिए ΔG < 0।"},{"s":"General Awareness","q":"As per the Ministry of Defence’s Year End Review 2024 (PIB), what is the number of C- 295 aircraft to be indigenously built by TASL in India?","o":["72","56","40","65"],"a":2,"e":"Of the 56 C-295 aircraft ordered, 40 are to be built in India by TASL.","qh":"रक्षा मंत्रालय की वषाेंत समीक्षा 2024 (PIB) के अनुसार, भारत में TASL द्वारा स्वदेशी रूप से निर्मित किए जाने वाले C-295 विमानों की संख्या कितनी है?","oh":["72","56","40","65"],"eh":"ऑर्डर किए गए 56 C-295 विमानों में से 40 भारत में TASL द्वारा बनाए जाने हैं।"},{"s":"General Awareness","q":"Which part of the Indian Constitution deals with special provisions for Scheduled Castes, Scheduled Tribes, and other backwards classes?","o":["Part III","Part IX","Part XVI","Part IV"],"a":2,"e":"Part XVI (Articles 330–342) has the special provisions for SCs, STs and backward classes.","qh":"भारतीय संविधान का कौन-सा भाग, अनुसूचित जातियों, अनुसूचित जनजातियों और अन्य पिछड़े वर्गों के लिए विशेष प्रावधानों से संबंधित है?","oh":["भाग III","भाग IX","भाग XVI","भाग IV"],"eh":"भाग XVI (अनुच्छेद 330–342) में SC, ST और पिछड़े वर्गों के लिए विशेष प्रावधान हैं।"},{"s":"General Awareness","q":"Which of the following correctly differentiates between RAM and ROM?","o":["ROM performs all logical operations, while RAM controls input devices","RAM is permanent memory while ROM is volatile","RAM loses its content when the computer is turned off, while ROM retains its data","ROM is used to store data temporarily during program execution"],"a":2,"e":"RAM is volatile and loses data when the power is off. ROM keeps its data.","qh":"निम्नलिखित में से कौन-सा, RAM और ROM के बीच सही अंतर का वर्णन करता है?","oh":["ROM सभी तार्किक संचालन करता है, जबकि RAM इनपुट डिवाइस को नियंत्रित करता है","RAM स्थायी मेमोरी है जबकि ROM लोपशील (volatile) है","जब कंप्यूटर बंद कर दिया जाता है तो RAM अपना कंटेंट खो देता है, जबकि ROM अपना डेटा बरकरार रखता है","ROM का उपयोग प्रोग्राम निष्पादन के दौरान अस्थायी रूप से डेटा संग्रहीत करने के लिए किया जाता है"],"eh":"RAM अस्थायी (वोलेटाइल) है और बिजली बंद होने पर डेटा खो देती है। ROM अपना डेटा बनाए रखती है।"},{"s":"General Awareness","q":"What minimum legal practice experience did the Supreme Court mandate on 20 May 2025 for applicants to the Civil Judge (Junior Division) post?","o":["Three years of legal practice experience","Four years of legal practice experience","One year of legal practice experience","Two years of legal practice experience"],"a":0,"e":"On 20 May 2025 the SC brought back a minimum of 3 years' practice for Civil Judge (Junior Division).","qh":"सवोंच्च न्यायालय ने, 20 मई 2025 को सिविल जज (जूनियर डिवीजन) पद के आवेदकों के लिए न्यूनतम कितना वकालत अनुभव अनिवार्य किया है?","oh":["तीन वर्ष का वकालत का अनुभव","चार वर्ष का वकालत का अनुभव","एक वर्ष का वकालत का अनुभव","दो वर्ष का वकालत का अनुभव"],"eh":"20 मई 2025 को सर्वोच्च न्यायालय ने सिविल जज (कनिष्ठ श्रेणी) के लिए न्यूनतम 3 वर्ष की वकालत की शर्त फिर से लागू की।"},{"s":"General Awareness","q":"Which country ranked 10th in the Climate Change Performance Index (CCPI) 2025 report released at the annual UN climate conference in Baku?","o":["Brazil","China","South Africa","India"],"a":3,"e":"India ranked 10th in CCPI 2025.","qh":"बाकू में आयोजित वार्षिक UN जलवायु सम्मेलन में जारी जलवायु परिवर्तन प्रदर्शन सूचकांक (CCPI) वें 2025 रिपोर्ट में, कौन-सा देश 10 स्थान पर रहा?","oh":["ब्राज़ील","चीन","दक्षिण अफ्रीका","भारत"],"eh":"CCPI 2025 में भारत 10वें स्थान पर रहा।"},{"s":"General Awareness","q":"The _____ developed 32-bit microprocessors for space applications named VIKRAM3201 and KALPANA3201.","o":["Indian Space Research Organization","European Space Agency","National Aeronautics and Space Administration","Japan Aerospace Exploration Agency"],"a":0,"e":"ISRO (with SCL Mohali) developed the VIKRAM3201 and KALPANA3201 processors.","qh":"___________ ने अंतरिक्ष अनुप्रयोगों के लिए VIKRAM3201 और KALPANA3201 नामक 32-बिट माइक्रोप्रोसेसर विकसित किए।","oh":["भारतीय अंतरिक्ष अनुसंधान संगठन","यूरोपियन स्पेस एजेंसी","नेशनल एयरोनॉटिक्स एंड स्पेस एडमिनिस्ट्रेशन","जापान एयरोस्पेस एक्सप्लोरेशन एजेंसी"],"eh":"इसरो (SCL मोहाली के साथ) ने VIKRAM3201 और KALPANA3201 प्रोसेसर विकसित किए।"},{"s":"General Awareness","q":"In which of the following years was the Bharatmala Pariyojana approved by the Government of India covering a length of 34,800 km to improve connectivity and reduce logistics cost in the country?","o":["2014","2017","2024","2022"],"a":1,"e":"Bharatmala Pariyojana Phase-I was approved in 2017.","qh":"भारत सरकार द्वारा देश में कनेक्टिविटी सुधार और लॉजिस्टिक्स लागत को कम करने के लिए 34,800 km लंबाई को कवर करने वाली भारतमाला परियोजना को निम्नलिखित में से किस वर्ष मंजूरी दी गई थी?","oh":["2014","2017","2024","2022"],"eh":"भारतमाला परियोजना चरण-I को 2017 में मंजूरी मिली।"},{"s":"General Awareness","q":"Which of the following sectors contributed significantly to India’s GDP growth after the 1991 reforms?","o":["Agriculture","Public sector enterprises","Services sector","Cottage industries"],"a":2,"e":"After 1991 the services sector led India's GDP growth.","qh":"1991 के सुधारों के बाद निम्नलिखित में से किस क्षेत्र ने भारत की सकल घरेलू उत्पाद की वृद्धि में महत्वपूर्ण योगदान दिया?","eh":"1991 के बाद सेवा क्षेत्र ने भारत की GDP वृद्धि का नेतृत्व किया।"},{"s":"General Awareness","q":"Sharing borders with the states of Kerala and Karnataka, Mudumalai National Park of Tamil Nadu is a part of which biosphere reserve of India?","o":["Nilgiri Biosphere Reserve","Kangchendzonga Biosphere Reserve","Agasthyamalai Biosphere Reserve","Nokrek Biosphere Reserve"],"a":0,"e":"Mudumalai is part of the Nilgiri Biosphere Reserve.","qh":"केरल और कर्नाटक राज्य के साथ सीमा साझा करने वाला, तमिलनाडु का मुदुमलाई राष्ट्रीय उद्यान भारत के किस बायोस्फीयर रिजर्व का हिस्सा है?","oh":["नीलगिरि बायोस्फीयर रिजर्व","कंचनजंगा बायोस्फीयर रिजर्व","अगस्त्यमलाई बायोस्फीयर रिजर्व","नोकरेक बायोस्फीयर रिजर्व"],"eh":"मुदुमलाई नीलगिरि जैवमंडल आरक्षित क्षेत्र का भाग है।"},{"s":"Mathematics","q":"The average weight of Gopal, Akshay and Atul is 45 kg. If the average weight of Gopal and Akshay is 44 kg and that of Akshay and Atul is 46 kg, then the weight of Akshay (in kg) is:","o":["65","55","60","45"],"a":3,"e":"Akshay = 88 + 92 − 135 = 45 kg.","qh":"गोपाल, अक्षय और अतुल का औसत वज़न 45 kg है। यदि गोपाल और अक्षय का औसत वज़न 44 kg है तथा अक्षय और अतुल का औसत वज़न 46 kg है, तो अक्षय का वज़न (kg में) ज्ञात कीजिए।","oh":["65","55","60","45"],"eh":"अक्षय = 88 + 92 − 135 = 45 kg।"},{"s":"Mathematics","q":"What smallest number should be added to 74978 so that the sum is completely divisible by 24?","o":["22","17","20","26"],"a":0,"e":"74978 = 24 × 3124 + 2, so add 24 − 2 = 22.","qh":"वह सबसे छोटी संख्या ज्ञात कीजिए जिसे 74978 में जोड़ने पर प्राप्त योगफल 24 से पूर्णतः विभाज्य हो जाए।","oh":["22","17","20","26"],"eh":"74978 = 24 × 3124 + 2, अतः 24 − 2 = 22 जोड़ें।"},{"s":"Mathematics","q":"","o":["39","45","49","48"],"a":0,"img":"data/img/ntpc-2025-aug-28-s2/003ma-q0.png","e":"8² + √(81 − 4 × 5) − 14 → 64 + 9 − 20 − 14 = 39 (as in the figure).","oh":["39","45","49","48"],"eh":"8² + √(81 − 4 × 5) − 14 → 64 + 9 − 20 − 14 = 39 (चित्र के अनुसार)।"},{"s":"Mathematics","q":"A number, when increased by 80%, gives 2520. The number is:","o":["4200","1400","2800","700"],"a":1,"e":"1.8x = 2520, so x = 1400.","qh":"एक संख्या में 80% की वृद्धि करने पर 2520 प्राप्त होता है। वह संख्या ज्ञात कीजिए।","oh":["4200","1400","2800","700"],"eh":"1.8x = 2520, अतः x = 1400।"},{"s":"Mathematics","q":"The LCM of 4³ × 6² × 15, 4² × 15² × 19 and 6³ × 15² × 19² is:","o":["2⁸ x 3⁴ x 5² x 19²","2⁸ x 3⁵ x 5³ x 19²","2⁸ x 3⁵ x 5² x 19²","2⁹ x 3⁵ x 5² x 19²"],"a":2,"e":"The three numbers are 2⁸·3³·5, 2⁴·3²·5²·19 and 2³·3⁵·5²·19². The LCM takes the highest powers: 2⁸ × 3⁵ × 5² × 19².","qh":"3 4 × 6 × 15, 4 × 15 × 19 और 6 × 15 × 19 का लघुत्तम समापवर्त्य (LCM) ज्ञात कीजिए। 9 2","eh":"तीनों संख्याएँ 2⁸·3³·5, 2⁴·3²·5²·19 और 2³·3⁵·5²·19² हैं। LCM में सबसे बड़ी घातें ली जाती हैं: 2⁸ × 3⁵ × 5² × 19²।"},{"s":"Mathematics","q":"If one interior angle of a regular polygon is greater than its exterior angle by 144°, how many sides does the polygon have?","o":["21","19","18","20"],"a":3,"e":"I − E = 144 and I + E = 180, so E = 18° and n = 360/18 = 20.","qh":"यदि किसी सम बहुभुज का एक अंतः कोण उसके बहिष्कोण से 144° अधिक है, तो बहुभुज में कितनी भुजाएँ होंगी?","oh":["21","19","18","20"],"eh":"I − E = 144 और I + E = 180, अतः E = 18° और n = 360/18 = 20।"},{"s":"Mathematics","q":"","o":["","","",""],"a":3,"img":"data/img/ntpc-2025-aug-28-s2/007ma-q0.png","oi":["data/img/ntpc-2025-aug-28-s2/007ma-o1.png","data/img/ntpc-2025-aug-28-s2/007ma-o2.png","data/img/ntpc-2025-aug-28-s2/007ma-o3.png","data/img/ntpc-2025-aug-28-s2/007ma-o4.png"],"e":"P fills the tank in 42 h and Q in 21 h. In 7 h they fill 1/2, which R empties in 9 h, so R = 1/18. P + Q − R = 1/42 + 1/21 − 1/18 = 1/63, i.e. 63 hours.","eh":"P टंकी को 42 घंटे में और Q 21 घंटे में भरता है। 7 घंटे में वे 1/2 भरते हैं, जिसे R 9 घंटे में खाली करता है, अतः R = 1/18। P + Q − R = 1/42 + 1/21 − 1/18 = 1/63, अर्थात 63 घंटे।"},{"s":"Mathematics","q":"Anshuman and Kunal together invested ₹48,300 in a business. At the end of the year, out of a total profit of ₹14,000, Kunal's share was ₹6,000. What was the difference between their investments?","o":["₹5,940","₹6,500","₹7,640","₹6,900"],"a":3,"e":"Kunal's share = 6/14 = 3/7, so he invested 20700 and Anshuman 27600. Difference = ₹6,900.","qh":"अंशुमान और कुणाल ने मिलकर एक व्यवसाय में ₹48,300 का निवेश किया। वर्ष के अंत में, ₹14,000 के कुल लाभ में से, कुणाल का हिस्सा ₹6,000 था। उनके निवेशों में कितना अंतर था?","oh":["₹5,940","₹6,500","₹7,640","₹6,900"],"eh":"कुणाल का हिस्सा = 6/14 = 3/7, अतः उसने 20700 और अंशुमान ने 27600 निवेश किए। अंतर = ₹6,900।"},{"s":"Mathematics","q":"Simplify: x(8x − 7) + 7(x² − 5) + 14","o":["−15x² − 7x + 21","15x² − 7x − 21","−15x² − 7x − 21","15x² − 7x + 21"],"a":1,"e":"8x² − 7x + 7x² − 35 + 14 = 15x² − 7x − 21.","qh":"सरल कीजिए: x(8x − 7) + 7(x − 5) + 14 2","eh":"8x² − 7x + 7x² − 35 + 14 = 15x² − 7x − 21।"},{"s":"Mathematics","q":"Yash travels 152 km at 38 km/hr, the next 189 km at 63 km/hr and the next 375 km at 75 km/hr. What is his average speed (in km/hr) for the whole journey? (Round off your answer to two decimal places)","o":["59.67","51.83","58.22","70.03"],"a":0,"e":"Time = 4 + 3 + 5 = 12 h for 716 km, so average = 59.67 km/h.","qh":"यश, 152 km की यात्रा 38 km/hr की चाल से, अगली 189 km की यात्रा 63 km/hr की चाल से और उससे अगली 375 km की यात्रा 75 km/hr की चाल से करता है। संपूर्ण यात्रा के लिए उसकी औसत चाल (km/hr में) कितनी है? (अपने उत्तर को दशमलव के दो स्थानों तक पूणाेंकित कीजिए)","oh":["59.67","51.83","58.22","70.03"],"eh":"716 km के लिए समय = 4 + 3 + 5 = 12 घंटे, अतः औसत = 59.67 km/h।"},{"s":"Mathematics","q":"The cost of 9 pens and 9 pencils is ₹252. If the cost of a pen decreases by ₹1 and the cost of a pencil increases by ₹3, then the cost of 13 pens and 3 pencils is ₹100. What is the original cost of 10 pens and 19 pencils?","o":["₹513","₹517","₹514","₹516"],"a":2,"e":"p + c = 28 and 13(p − 1) + 3(c + 3) = 100, so p = 2 and c = 26. 10p + 19c = 20 + 494 = ₹514.","qh":"9 पेन और 9 पेंसिल की कीमत ₹252 है। यदि पेन की कीमत ₹1 प्रति पेन कम हो जाती है और पेंसिल की कीमत ₹3 प्रति पेंसिल बढ़ जाती है, तो 13 पेन और 3 पेंसिल की कीमत ₹100 हो जाती है। 10 पेन और 19 पेंसिल की मूल कीमत कितनी होगी?","oh":["₹513","₹517","₹514","₹516"],"eh":"p + c = 28 और 13(p − 1) + 3(c + 3) = 100, अतः p = 2 और c = 26। 10p + 19c = 20 + 494 = ₹514।"},{"s":"Mathematics","q":"Find the value of: [428 ÷ {17 + 8 × ( 5 − 7 )}].","o":["428","429","427","426"],"a":0,"e":"17 + 8 × (−2) = 1, and 428 ÷ 1 = 428.","qh":"[428 ÷ {17 + 8 × ( 5 − 7 )}] का मान ज्ञात कीजिए।","oh":["428","429","427","426"],"eh":"17 + 8 × (−2) = 1, और 428 ÷ 1 = 428।"},{"s":"Mathematics","q":"The sum of two numbers is 121 and their L.C.M. is 264. What are the two numbers?","o":["81, 40","86, 35","88, 33","93, 28"],"a":2,"e":"88 + 33 = 121 and LCM(88, 33) = 264.","qh":"दो संख्याओं का योगफल 121 है और उनका लघुत्तम समापवर्त्य (L.C.M.) 264 है। वे दोनों संख्याएं ज्ञात कीजिए।","oh":["81, 40 2","86, 35","88, 33","93, 28"],"eh":"88 + 33 = 121 और LCM(88, 33) = 264।"},{"s":"Mathematics","q":"If the interest earned during the 2nd year on a certain sum is ₹1,760, and the rate of interest is 10% per annum compounded annually, then the sum is:","o":["₹16,405","₹15,495","₹16,000","₹15,990"],"a":2,"e":"2nd-year CI = 0.11P = 1760, so P = ₹16,000.","qh":"यदि किसी निश्चित धनराशि पर दूसरे वर्ष के दौरान अर्जित ब्याज ₹1,760 है, और ब्याज की दर 10% वार्षिक है जो वार्षिक रूप से संयोजित होती है, तो धनराशि ज्ञात कीजिए।","oh":["₹16,405","₹15,495 2 2 2 3 2 2","₹16,000","₹15,990"],"eh":"दूसरे वर्ष का चक्रवृद्धि ब्याज = 0.11P = 1760, अतः P = ₹16,000।"},{"s":"Mathematics","q":"A dealer wants to make a 20% profit on a smart watch that costs him ₹1,575. To attract customers, he plans to offer a 10% discount on the listed price. At what price should he list the smart watch to achieve his desired profit?","o":["₹2,100","₹1,918","₹1,654","₹1,890"],"a":0,"e":"SP = 1575 × 1.2 = 1890 = 0.9 × list price, so list = ₹2,100.","qh":"एक डीलर उस स्मार्ट वॉच पर 20% का लाभ अर्जित करना चाहता है जिसका क्रय मूल्य ₹1,575 है। ग्राहकों को आकर्षित करने के लिए, वह अंकित मूल्य पर 10% की छूट देने की योजना बनाता है। उसे अपना वांछित लाभ अर्जित करने के लिए स्मार्ट वॉच का अंकित मूल्य कितना रखना चाहिए?","oh":["₹2,100","₹1,918","₹1,654","₹1,890"],"eh":"विक्रय मूल्य = 1575 × 1.2 = 1890 = 0.9 × सूची मूल्य, अतः सूची मूल्य = ₹2,100।"},{"s":"Mathematics","q":"Find the simple interest (in ₹) if a sum of ₹400 is borrowed for 4.5 years at 20% per annum rate of interest.","o":["460","360","410","340"],"a":1,"e":"SI = 400 × 20 × 4.5/100 = ₹360.","qh":"यदि ₹400 की राशि 4.5 वर्ष के लिए 20% वार्षिक ब्याज दर पर उधार ली जाती है, तो साधारण ब्याज (₹ में) ज्ञात कीजिए।","oh":["460","360","410","340"],"eh":"साधारण ब्याज = 400 × 20 × 4.5/100 = ₹360।"},{"s":"Mathematics","q":"6 years ago, the age of a father was 34 years more than twice his son's age. After how many years, from now, will he be twice his son's age?","o":["23","28","26","24"],"a":1,"e":"F − 6 = 2(S − 6) + 34, so F = 2S + 28. F + x = 2(S + x) gives x = 28.","qh":"6 वर्ष पहले, एक पिता की आयु उसके पुत्र की आयु के दोगुने से 34 वर्ष अधिक थी। अब से कितने वर्षों बाद, उसकी आयु उसके पुत्र की आयु की दोगुनी हो जाएगी?","oh":["23","28","26","24"],"eh":"F − 6 = 2(S − 6) + 34, अतः F = 2S + 28। F + x = 2(S + x) से x = 28।"},{"s":"Mathematics","q":"","o":["","","",""],"a":0,"img":"data/img/ntpc-2025-aug-28-s2/018ma-q0.png","oi":["data/img/ntpc-2025-aug-28-s2/018ma-o1.png","data/img/ntpc-2025-aug-28-s2/018ma-o2.png","data/img/ntpc-2025-aug-28-s2/018ma-o3.png","data/img/ntpc-2025-aug-28-s2/018ma-o4.png"],"e":"Numerator: sin⁴A − cos⁴A + 1 = sin²A − cos²A + 1 = 2sin²A. Denominator: 1 + cot²A = cosec²A. Result = 2sin⁴A.","eh":"अंश: sin⁴A − cos⁴A + 1 = sin²A − cos²A + 1 = 2sin²A। हर: 1 + cot²A = cosec²A। परिणाम = 2sin⁴A।"},{"s":"Mathematics","q":"Pipe A can fill a tank in 16 hours, pipe B can fill the same tank in 21 hours and pipe C can fill the same tank in 15 hours. The time taken by them to fill the same tank if they operate together is::","o":["","","",""],"a":1,"oi":["data/img/ntpc-2025-aug-28-s2/019ma-o1.png","data/img/ntpc-2025-aug-28-s2/019ma-o2.png","data/img/ntpc-2025-aug-28-s2/019ma-o3.png","data/img/ntpc-2025-aug-28-s2/019ma-o4.png"],"e":"1/16 + 1/21 + 1/15 = 297/1680 per hour, so time = 1680/297 = 5 65/99 hours.","qh":"पाइप A किसी टैंक को 16 घंटे में भर सकता है, पाइप B उसी टैंक को 21 घंटे में भर सकता है और पाइप C उसी टैंक को 15 घंटे में भर सकता है। यदि वे सभी एक-साथ चालू कर दिए जाएं, तो उसी टैंक को भरने में कितना समय लगेगा?","eh":"1/16 + 1/21 + 1/15 = 297/1680 प्रति घंटा, अतः समय = 1680/297 = 5 65/99 घंटे।"},{"s":"Mathematics","q":"Five solid cubes, each of volume 512000 cm³, are joined end to end to form a cuboid. What is the lateral surface area (in cm²) of the cuboid?","o":["76949","76903","76800","76820"],"a":2,"e":"Side = 80, so the cuboid is 400 × 80 × 80. LSA = 2(400 + 80) × 80 = 76800 cm².","qh":"पाँच ठोस घन, जिनमें से प्रत्येक का आयतन 512000 cm³ है, उनके सिरों को जोड़कर एक घनाभ बनाया जाता है। घनाभ का पार्श्व पृष्ठीय क्षेत्रफल (cm² में) कितना होगा?","oh":["76949","76903","76800","76820"],"eh":"भुजा = 80, अतः घनाभ 400 × 80 × 80 है। पार्श्व पृष्ठीय क्षेत्रफल = 2(400 + 80) × 80 = 76800 cm²।"},{"s":"Mathematics","q":"The marks scored by 10 students are given below. 19, 15, 10, 14, 13, 18, 19, 19, 11, 11 The mode of the data is:","o":["19","20","15","10"],"a":0,"e":"19 appears 3 times, the most of any value.","qh":"10 विद्यार्थियों द्वारा प्राप्त अंक नीचे दिए गए हैं। 19, 15, 10, 14, 13, 18, 19, 19, 11, 11 आंकड़ों का बहुलक ज्ञात कीजिए।","oh":["19","20","15","10"],"eh":"19 तीन बार आता है, जो किसी भी अन्य मान से अधिक है।"},{"s":"Mathematics","q":"A shopkeeper lists the price of a fan at 50% above its cost price and offers a 30% discount on its list price. If he earns a profit of ₹91, then what is the list price (in ₹) of the fan?","o":["2,774","2,697","2,730","3,025"],"a":2,"e":"SP = 0.7 × 1.5C = 1.05C, so profit = 0.05C = 91 and C = 1820. List = 1.5C = ₹2,730.","qh":"एक दुकानदार एक पंखे का मूल्य उसके क्रय मूल्य से 50% अधिक अंकित करता है तथा इसके अंकित मूल्य पर 30% की छूट देता है। यदि वह ₹91 का लाभ अर्जित करता है, तो पंखे का अंकित मूल्य (₹ में) ज्ञात कीजिए।","oh":["2,774","2,697","2,730","3,025"],"eh":"विक्रय मूल्य = 0.7 × 1.5C = 1.05C, अतः लाभ = 0.05C = 91 और C = 1820। सूची मूल्य = 1.5C = ₹2,730।"},{"s":"Mathematics","q":"Which of the following numbers divides 2,45,015?","o":["2","11","15","5"],"a":3,"e":"245015 ends in 5, so 5 divides it. Its digit sum (17) isn't divisible by 3, so 15 doesn't.","qh":"निम्नलिखित में से कौन-सी संख्या, 2,45,015 को विभाजित करती है?","oh":["2","11","15","5"],"eh":"245015 का अंतिम अंक 5 है, अतः यह 5 से विभाज्य है। इसके अंकों का योग (17) 3 से विभाज्य नहीं है, अतः 15 से नहीं।"},{"s":"Mathematics","q":"If the third proportional of 9 and 51 be x, then what is the value of x?","o":["287","288","291","289"],"a":3,"e":"x = 51²/9 = 2601/9 = 289.","qh":"यदि 9 और 51 का तृतीयानुपाती x हो, तो x का मान ज्ञात कीजिए।","oh":["287","288","291","289"],"eh":"x = 51²/9 = 2601/9 = 289।"},{"s":"Mathematics","q":"The marked price of an article is ₹4,500. It is sold at successive discounts of 25% and 20%. Find the selling price of the article (in ₹).","o":["2,700","2,800","2,750","2,900"],"a":0,"e":"4500 × 0.75 × 0.80 = ₹2,700.","qh":"एक वस्तु का अंकित मूल्य ₹4,500 है। इसे 25% और 20% की क्रमिक छूटों पर बेचा जाता है। वस्तु का विक्रय मूल्य (₹ में) ज्ञात कीजिए।","oh":["2,700","2,800","2,750","2,900"],"eh":"4500 × 0.75 × 0.80 = ₹2,700।"},{"s":"Mathematics","q":"Mahesh bought some pens at the rate of ₹150 a dozen. He sold them for ₹44 each. His profit percentage is ______%.","o":["256","250","254","252"],"a":3,"e":"CP = 150/12 = 12.5 per pen. Profit = 31.5/12.5 × 100 = 252%.","qh":"महेश ने ₹150 प्रति दर्जन की दर से कुछ पेन खरीदे। उसने उन्हें ₹44 प्रति पेन की दर से बेचा। उसका लाभ प्रतिशत ______% है।","oh":["256","250","254","252"],"eh":"प्रति पेन क्रय मूल्य = 150/12 = 12.5। लाभ = 31.5/12.5 × 100 = 252%।"},{"s":"Mathematics","q":"A toy designer is making a spherical ball with a radius of 6 cm. What is the surface area of the ball? (Use π = 3.14)","o":["678.24 cm²","301.44 cm²","452.16 cm²","282.74 cm²"],"a":2,"e":"4πr² = 4 × 3.14 × 36 = 452.16 cm².","qh":"एक खिलौना डिज़ाइनर 6 cm त्रिज्या वाली एक गोलाकार गेंद बना रहा है। गेंद का पृष्ठीय क्षेत्रफल ज्ञात कीजिए। (π = 3.14 का उपयोग कीजिए।)","oh":["678.24 cm²","301.44 cm²","452.16 cm²","282.74 cm²"],"eh":"4πr² = 4 × 3.14 × 36 = 452.16 cm²।"},{"s":"Mathematics","q":"The population of a district is 374000, out of which 170000 are males. 78% of the population is literate. If 72% males are literate, then what percentage of females are literate?","o":["85%","83%","81%","80%"],"a":1,"e":"Literate = 291720, literate males = 122400, so literate females = 169320 of 204000 = 83%.","qh":"एक जिले की जनसंख्या 374000 है, जिसमें से 170000 पुरुष हैं। 78% जनसंख्या साक्षर है। यदि 72% पुरुष साक्षर हैं, तो कितने प्रतिशत महिलाएँ साक्षर हैं?","oh":["85%","83%","81%","80%"],"eh":"साक्षर = 291720, साक्षर पुरुष = 122400, अतः साक्षर महिलाएँ = 204000 में से 169320 = 83%।"},{"s":"Mathematics","q":"Arjun and Malaika have to travel from Delhi to Kanpur in their respective cars. Arjun is driving at 140 km/hr while Malaika is driving at 65 km/hr. Find the time taken by Malaika to reach Kanpur if Arjun takes 13 hours.","o":["25 hours","34 hours","26 hours","28 hours"],"a":3,"e":"Distance = 140 × 13 = 1820 km, and Malaika takes 1820/65 = 28 h.","qh":"अर्जुन और मलाइका को अपनी-अपनी कारों से दिल्ली से कानपुर जाना है। अर्जुन 140 km/hr की चाल से ड्राइव कर रहा है, जबकि मलाइका 65 km/hr की चाल से ड्राइव कर रही है। यदि अर्जुन को कानपुर पहुँचने में 13 घंटे लगते हैं, तो मलाइका को कितना समय लगेगा?","oh":["25 घंटे","34 घंटे","26 घंटे","28 घंटे"],"eh":"दूरी = 140 × 13 = 1820 km, और मलाइका को 1820/65 = 28 घंटे लगते हैं।"},{"s":"Mathematics","q":"Anand, Preeti and Dev invested ₹1,310, ₹1,350 and ₹1,140, respectively to start a business. If the profit at the end of the year is ₹1,630, what is Dev's share of the profit?","o":["₹488","₹487","₹489","₹490"],"a":2,"e":"Dev = 1140/3800 × 1630 = ₹489.","qh":"आनंद, प्रीति और देव ने एक व्यवसाय शुरू करने के लिए क्रमशः ₹1,310, ₹1,350 और ₹1,140 का निवेश किया। यदि वर्ष के अंत में लाभ ₹1,630 है, तो लाभ में देव का हिस्सा कितना है?","oh":["₹488","₹487","₹489","₹490"],"eh":"देव = 1140/3800 × 1630 = ₹489।"},{"s":"General Intelligence and Reasoning","q":"What should come in place of the question mark (?) in the given series? 27 31 40 56 81 ?","o":["121","120","118","117"],"a":3,"e":"Differences are squares 2², 3², 4², 5², then 6²: 81 + 36 = 117.","qh":"दी गई श्रृंखला में प्रश्न-चिन्ह (?) के स्थान पर क्या आएगा? 27 31 40 56 81 ?","oh":["121","120","118","117"],"eh":"अंतर वर्ग संख्याएँ हैं 2², 3², 4², 5², फिर 6²: 81 + 36 = 117।"},{"s":"General Intelligence and Reasoning","q":"In a certain code language, A $ B means ‘A is the son of B’ A + B means ‘A is the brother of B’ A @ B means ‘A is the wife of B’ A ÷ B means ‘A is the father of B’ Based on the above, how is E related to N if ‘E @ F $ G ÷ M + N’?","o":["Brother's daughter","Brother's wife","Wife","Daughter"],"a":1,"e":"F is G's son and M's brother, so F is N's brother. E, F's wife, is N's brother's wife.","qh":"एक निश्चित कूट भाषा में, A $ B का अर्थ है कि ‘A, B का पुत्र है’ A + B का अर्थ है कि ‘A, B का भाई है’ A @ B का अर्थ है कि ‘A, B की पत्नी है’ A ÷ B का अर्थ है कि ‘A, B का पिता है’ उपरोक्त के आधार पर, यदि ‘E @ F $ G ÷ M + N’ है, तो E का N से क्या संबंध है?","oh":["भाई की पुत्री","भाई की पत्नी","पत्नी","पुत्री"],"eh":"F, G का पुत्र और M का भाई है, अतः F, N का भाई है। F की पत्नी E, N की भाभी है।"},{"s":"General Intelligence and Reasoning","q":"What should come in place of the question mark (?) in the given series based on the English alphabetical order? WVH BAM GFR LKW ?","o":["QPB","QBP","QWE","QEW"],"a":0,"e":"Each letter moves +5: L→Q, K→P, W→B gives QPB.","qh":"अंग्रेजी वर्णमाला क्रम के आधार पर, दी गई शृंखला में प्रश्न-चिह्न (?) के स्थान पर क्या आना चाहिए? WVH BAM GFR LKW ?","oh":["QPB","QBP","QWE","QEW"],"eh":"प्रत्येक अक्षर +5 खिसकता है: L→Q, K→P, W→B, अतः QPB।"},{"s":"General Intelligence and Reasoning","q":"Based on the English alphabetical order, three of the following four letter-cluster pairs are alike in a certain way and thus form a group. Which letter-cluster pair DOES NOT belong to that group? (Note: The odd one out is not based on the number of consonants/vowels or their position in the letter-cluster.)","o":["PT-KQ","JN-EK","MQ-HN","SW-NU"],"a":3,"e":"The others are −5, −3 (P→K, T→Q). In SW-NU, W→U is −2.","qh":"अंग्रेजी वर्णमाला क्रम पर आधारित, निम्नलिखित चार अक्षर-समूह युग्मों में से तीन एक निश्चित तरीके से समान हैं और इस प्रकार वे एक ग्रुप बनाते हैं। कौन-सा अक्षर-समूह युग्म, उस ग्रुप से संबंधित नहीं है? (नोट: असंगत अक्षर-समूह युग्म, व्यंजनों/स्वरों की संख्या या उनकी स्थिति पर आधारित नहीं है।)","oh":["PT-KQ","JN-EK","MQ-HN","SW-NU"],"eh":"अन्य में −5, −3 है (P→K, T→Q)। SW-NU में W→U, −2 है।"},{"s":"General Intelligence and Reasoning","q":"Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements. Statements: Some notes are books. All books are tables. Conclusion (I): Some notes are tables. Conclusions (II): All tables are books.","o":["Neither conclusion (I) nor (II) follows.","Only conclusion (II) follows.","Both conclusions (I) and (II) follow.","Only conclusion (I) follows."],"a":3,"e":"Some notes are books and all books are tables, so some notes are tables: (I) follows. (II) doesn't.","qh":"दिए गए कथनों और निष्कर्षों को ध्यानपूर्वक पढ़ें। यह मानते हुए कि कथनों में दी गई जानकारी सत्य है, भले ही वह सामान्यतः ज्ञात तथ्यों से भिन्न प्रतीत होती हो, तय करें कि दिए गए निष्कर्षों में से कौन-से निष्कर्ष कथनों का तार्किक रूप से अनुसरण करते हैं। कथन: सभी पत्र, मेल हैं। सभी अनुसूचियाँ, मेल हैं। निष्कर्ष: (I) कुछ पत्र, अनुसूचियाँ हैं। (II) कुछ मेल, अनुसूचियाँ हैं।","oh":["न तो निष्कर्ष (I) और न ही (II) अनुसरण करता है।","केवल निष्कर्ष (I) अनुसरण करता है।","निष्कर्ष (I) और (II) दोनों अनुसरण करते हैं।","केवल निष्कर्ष (II) अनुसरण करता है।"],"eh":"कुछ नोट किताबें हैं और सभी किताबें मेज़ हैं, अतः कुछ नोट मेज़ हैं: (I) अनुसरण करता है। (II) नहीं करता।"},{"s":"General Intelligence and Reasoning","q":"Select the set in which the numbers are related in the same way as are the numbers of the following sets. (NOTE: Operations should be performed on the whole numbers, without breaking down the numbers into their constituent digits. E.g. 13 – Operations on 13 such as adding to/subtracting from/multiplying with 13 can be performed. Breaking down 13 into 1 and 3 and then performing mathematical operations on 1 and 3 is not allowed.) (16, 63, 16) (36, 111, 4)","o":["(47, 144, 4)","(48, 162, 15)","(44, 155, 20)","(1, 12, 6)"],"a":0,"e":"2nd = 3 × 1st + (3rd − 1): 3 × 16 + 15 = 63, 3 × 36 + 3 = 111, 3 × 47 + 3 = 144.","qh":"उस समुच्चय का चयन कीजिए जिसमें संख्याएँ उसी तरीके से संबंधित हैं जिस तरीके से निम्नलिखित समुच्चयों की संख्याएँ संबंधित हैं। नोट: संख्याओं को उनके घटक अंकों में तोड़े बिना संक्रियाएँ पूर्ण संख्याओं पर की जानी चाहिए। उदाहरण के लिए, 13 को लीजिए – 13 पर संक्रियाएँ जैसे 13 में जोड़ना/ 13 में से घटाना/ 13 से गुणा करना आदि, की जा सकती है। 13 को 1 और 3 में तोड़ना और फिर 1 तथा 3 पर गणितीय संक्रियाएँ करने की अनुमति नहीं है।) (16, 63, 16) (36, 111, 4)","oh":["(47, 144, 4)","(48, 162, 15)","(44, 155, 20)","(1, 12, 6)"],"eh":"दूसरी = 3 × पहली + (तीसरी − 1): 3 × 16 + 15 = 63, 3 × 36 + 3 = 111, 3 × 47 + 3 = 144।"},{"s":"General Intelligence and Reasoning","q":"If ‘A’ stands for ‘÷’, ‘B’ stands for ‘x’, ‘C’ stands for ‘+’ and ‘D’ stands for ‘−’, what will come in place of the question mark (?) in the following equation? 48 D 14 B 3 C 27 A 3 = ?","o":["24","31","15","37"],"a":2,"e":"48 − 14 × 3 + 27 ÷ 3 = 48 − 42 + 9 = 15.","qh":"यदि ‘A’ का अर्थ ‘÷’ है, ‘B’ का अर्थ ‘x’ है, ‘C’ का अर्थ ‘+’ है और ‘D’ का अर्थ ‘−’ है, तो निम्नलिखित समीकरण में प्रश्न-चिह्न (?) के स्थान पर क्या आएगा? 48 D 14 B 3 C 27 A 3 = ?","oh":["24","31","15","37"],"eh":"48 − 14 × 3 + 27 ÷ 3 = 48 − 42 + 9 = 15।"},{"s":"General Intelligence and Reasoning","q":"Based on the English alphabetical order, three of the following four letter-clusters are alike in a certain way and thus form a group. Which letter-cluster DOES NOT belong to that group? (Note: The odd one out is not based on the number of consonants/vowels or their position in the letter-cluster.)","o":["RXCJ","OUZG","KQVC","NTYE"],"a":3,"e":"The others are +6, +5, +7 (R→X→C→J). NTYE ends with +6.","qh":"अंग्रेजी वर्णमाला क्रम के आधार पर, निम्नलिखित चार अक्षर-समूहों में से तीन एक निश्चित तरीके से एकसमान हैं और इस प्रकार वे एक ग्रुप बनाते हैं। कौन-सा अक्षर-समूह उस ग्रुप से संबंधित नहीं है? (नोट: असंगत अक्षर-समूह, उसमें व्यंजनों/स्वरों की संख्या या उनकी स्थिति पर आधारित नहीं है।)","oh":["RXCJ","OUZG","KQVC","NTYE"],"eh":"अन्य में +6, +5, +7 है (R→X→C→J)। NTYE के अंत में +6 है।"},{"s":"General Intelligence and Reasoning","q":"BGLY is related to DJNB in a certain way based on the English alphabetical order. In the same way, JSTK is related to LVVN. To which of the given options is PBZT related, following the same logic?","o":["RWBY","REWB","REBW","RWYI"],"a":2,"e":"Pattern +2, +3, +2, +3: P→R, B→E, Z→B, T→W gives REBW.","qh":"अंग्रेजी वर्णमाला क्रम पर आधारित, एक निश्चित तरीके से BGLY का संबंध DJNB से है। उसी तरीके से, JSTK का संबंध LVVN से है। समान तर्क का अनुसरण करते हुए, दिए गए विकल्पों में से PBZT का संबंध किससे है?","oh":["RWBY","REWB","REBW","RWYI"],"eh":"पैटर्न +2, +3, +2, +3: P→R, B→E, Z→B, T→W, अतः REBW।"},{"s":"General Intelligence and Reasoning","q":"Seven people, I, J, K, L, M, N and O, are sitting in a row, facing north. Only J sits to the left of O. Only four people sit between J and I. Only K sits between M and N, and M is not an immediate neighbor of I. Who sits at the extreme right of the line?","o":["M","L","O","I"],"a":1,"e":"The order is J, O, M, K, N, I, L, so L is at the extreme right.","qh":"सात व्यक्ति, I, J, K, L, M, N और O, एक पंक्ति में उत्तर की ओर अभिमुख होकर बैठे हैं। केवल J, O के बाईं ओर बैठा है। J और I के बीच केवल चार व्यक्ति बैठे हैं। M और N के बीच केवल K बैठा है, तथा M, I का निकटतम पड़ोसी नहीं है। पंक्ति के दाईं छोर पर कौन बैठा है?","oh":["M","L","O","I"],"eh":"क्रम J, O, M, K, N, I, L है, अतः L सबसे दाएँ छोर पर है।"},{"s":"General Intelligence and Reasoning","q":"Refer to the following number and symbol series and answer the question that follows. Counting to be done from left to right only. (Left) 8 & % 1 @ 2 3 $ 9 & 6 Ω 4 # 5 * £ 7 (Right) If all the symbols are dropped from the series, which of the following will be fourth from the right?","o":["4","2","6","9"],"a":2,"e":"Numbers only: 8 1 2 3 9 6 4 5 7. Fourth from the right is 6.","qh":"निम्नलिखित संख्या और प्रतीक शृंखला का संदर्भ लीजिए तथा नीचे दिए गए प्रश्न का उत्तर दीजिए। गिनती केवल बाएँ से दाएँ की जानी चाहिए। (बाएँ) 8 & % 1 @ 2 3 $ 9 & 6 Ω 4 # 5 * £ 7 (दाएँ) यदि शृंखला से सभी प्रतीकों को हटा दिया जाए, तो निम्नलिखित में से कौन-सा, दाएँ से चौथा होगा?","oh":["4","2","6","9"],"eh":"केवल संख्याएँ: 8 1 2 3 9 6 4 5 7। दाएँ से चौथी 6 है।"},{"s":"General Intelligence and Reasoning","q":"Rahul starts from Point Y and drives 14 km towards the north. He then takes a right turn, drives 6 km, then he turns right and drives 20 km. He then takes a right turn and drives 12 km. He takes a final right turn, drives 6 km and stops at Point Z. How far (shortest distance) and towards which direction should he drive in order to reach Point Y again? (All turns are 90-degree turns only unless specified.)","o":["4 km towards the east","6 km towards the north","6 km towards the east","4 km towards the north"],"a":2,"e":"Net position: 6 km west of Y and 0 km north/south, so he drives 6 km east.","qh":"राहुल बिंदु Y से ड्राइव करना शुरू करता है और उत्तर की ओर 14 km ड्राइव करता है। फिर वह दाएं मुड़ता है और 6 km ड्राइव करता है, फिर वह दाएं मुड़ता है और 20 km ड्राइव करता है। फिर वह दाएं मुड़ता है और 12 km ड्राइव करता है। वह अंतिम बार दाएं मुड़ता है और 6 km ड्राइव करता है और बिंदु Z पर रुक जाता है। बिंदु Y पर फिर से वापस पहुंचने के लिए उसे कितनी दूरी (सबसे छोटी दूरी) और किस दिशा में ड्राइव करना चाहिए? (जब तक निर्दिष्ट न किया जाए, सभी मोड़ केवल 90-डिग्री मोड़ हैं।)","oh":["4 km पूर्व की ओर","6 km उत्तर की ओर","6 km पूर्व की ओर","4 km उत्तर की ओर"],"eh":"शुद्ध स्थिति: Y से 6 km पश्चिम और 0 km उत्तर/दक्षिण, अतः वह 6 km पूर्व जाता है।"},{"s":"General Intelligence and Reasoning","q":"RUWU is related to YBDB in a certain way based on the English alphabetical order. In the same way, JMOM is related to QTVT. To which of the given options is TWYW related, following the same logic?","o":["ADED","ACED","ADFD","AEEL"],"a":2,"e":"Each letter moves +7: T→A, W→D, Y→F, W→D gives ADFD.","qh":"अंग्रेजी वर्णमाला क्रम के आधार पर, एक निश्चित तरीके से RUWU का संबंध YBDB से है। उसी तरीके से, JMOM का संबंध QTVT से है। समान तर्क का अनुसरण करते हुए, TWYW का संबंध दिए गए विकल्पों में से किस विकल्प से है?","oh":["ADED","ACED","ADFD","AEEL"],"eh":"प्रत्येक अक्षर +7 खिसकता है: T→A, W→D, Y→F, W→D, अतः ADFD।"},{"s":"General Intelligence and Reasoning","q":"In a certain code language, ‘reading is important’ is written as ‘pb mk lo’ and ‘is it raining’ is coded as ‘jo mt pb’. How is ‘is’ coded in the given language?","o":["lo","mk","jo","pb"],"a":3,"e":"'is' is the common word and 'pb' is the common code.","qh":"एक निश्चित कूट भाषा में, ‘reading is important’ को ‘pb mk lo’ लिखा जाता है और ‘is it raining’ को ‘jo mt pb’ लिखा जाता है। दी गई भाषा में ‘is’ का कूट क्या होगा?","oh":["lo","mk","jo","pb"],"eh":"'is' उभयनिष्ठ शब्द है और 'pb' उभयनिष्ठ कूट है।"},{"s":"General Intelligence and Reasoning","q":"Seven boxes V, W, X, Y, Z, Q and R are kept one over the other but not necessarily in the same order. Only two boxes are kept below Z. Only one box is kept above W. Only one box is kept between W and Q.V is kept immediately above Y. R is kept at some place below X. How many boxes are kept between X and V?","o":["Three","Four","Two","One"],"a":1,"e":"Top to bottom: X, W, R, Q, Z, V, Y. Four boxes are between X and V.","qh":"सात बक्से V, W, X, Y, Z, Q और R एक के ऊपर एक रखे गए हैं, लेकिन जरूरी नहीं कि वे इसी क्रम में रखे गए हों। Z के नीचे केवल दो बक्से रखे गए हैं। W के ऊपर केवल एक बक्सा रखा गया है। W और Q के बीच केवल एक बक्सा रखा गया है। V को Y के ठीक ऊपर रखा गया है। R को X के नीचे किसी स्थान पर रखा गया है। X और V के बीच कितने बक्से रखे गए हैं?","oh":["तीन","चार","दो","एक"],"eh":"ऊपर से नीचे: X, W, R, Q, Z, V, Y। X और V के बीच चार बॉक्स हैं।"},{"s":"General Intelligence and Reasoning","q":"Seven people, I, J, K, L, P, Q and R are sitting in a row, facing north. Only J sits to the left of P. Only four people sit between J and I. Only K sits between R and Q. R is not an immediate neighbour of I. Who sits at the extreme right end of the line?","o":["R","L","K","I"],"a":1,"e":"The order is J, P, R, K, Q, I, L, so L is at the extreme right.","qh":"सात व्यक्ति I, J, K, L, P, Q और R उत्तर की ओर अभिमुख होकर एक पंक्ति में बैठे हैं। P के बाईं ओर केवल J बैठा है। J और I के बीच केवल चार व्यक्ति बैठे हैं। R और Q के बीच केवल K बैठा है। R, I का निकटतम पड़ोसी नहीं है। पंक्ति के दाईं छोर पर कौन बैठा है?","oh":["R","L","K","I"],"eh":"क्रम J, P, R, K, Q, I, L है, अतः L सबसे दाएँ छोर पर है।"},{"s":"General Intelligence and Reasoning","q":"Which of the following letter-number clusters will replace the question mark (?) in the given series to make it logically complete? JMR11 KNS20 LOT29 MPU38 ?","o":["NQU42","NQV47","NQU46","NQV56"],"a":1,"e":"Each letter moves +1 (M→N, P→Q, U→V) and the number +9, giving NQV47.","qh":"निम्नलिखित में से कौन-सा अक्षर-संख्या समूह, दी गई श्रृंखला को तार्किक रूप से पूर्ण बनाने के लिए प्रश्न- चिह्न (?) को प्रतिस्थापित करेगा? JMR11 KNS20 LOT29 MPU38 ?","oh":["NQU42","NQV47","NQU46","NQV56"],"eh":"प्रत्येक अक्षर +1 खिसकता है (M→N, P→Q, U→V) और संख्या +9, अतः NQV47।"},{"s":"General Intelligence and Reasoning","q":"If 1 is added to each odd digit and 2 is subtracted from each even digit in the number 7453186, how many digits will appear more than once in the new number thus formed?","o":["Two","Three","None","One"],"a":1,"e":"7453186 becomes 8264264. 2, 6 and 4 each repeat, so three digits.","qh":"यदि संख्या 7453186 में प्रत्येक विषम अंक में 1 जोड़ा जाए तथा प्रत्येक सम अंक में से 2 घटाया जाए, तो इस प्रकार बनी नई संख्या में कितने अंक एक से अधिक बार आएंगे?","oh":["दो","तीन","एक भी नहीं","एक"],"eh":"7453186, 8264264 बन जाता है। 2, 6 और 4 प्रत्येक दोहराए गए हैं, अतः तीन अंक।"},{"s":"General Intelligence and Reasoning","q":"What will come in the place of the question mark (?) in the following equation, if ‘+’ and ‘−’ are interchanged and ‘×’ and ‘÷’ are interchanged? 57 × 3 − 11 ÷ 7 + 42 = ?","o":["54","50","52","56"],"a":0,"e":"Becomes 57 ÷ 3 + 11 × 7 − 42 = 19 + 77 − 42 = 54.","qh":"यदि ‘+’ और ‘−’ को आपस में बादल दिया जाए तथा ‘×’ और ‘÷’ को आपस में बादल दिया जाए, तो निम्नलिखित समीकरण में प्रश्न-चिह्न (?) के स्थान पर क्या आएगा? 57 × 3 − 11 ÷ 7 + 42 = ?","oh":["54","50","52","56"],"eh":"यह 57 ÷ 3 + 11 × 7 − 42 = 19 + 77 − 42 = 54 बन जाता है।"},{"s":"General Intelligence and Reasoning","q":"In a certain code language, ‘BLUE’ is coded as ‘7524’ and ‘UNIT’ is coded as ‘1356’. What is the code for ‘U’ in the given code language?","o":["1","2","5","6"],"a":2,"e":"U is the only common letter and 5 the only common digit, so U = 5.","qh":"किसी निश्चित कूट भाषा में, ‘BLUE’ को ‘7524’ और ‘UNIT’ को ‘1356’ के रूप में कूटबद्ध किया गया है। दी गई कूट भाषा में ‘U’ के लिए कूट क्या है?","oh":["1","2","5","6"],"eh":"U एकमात्र उभयनिष्ठ अक्षर और 5 एकमात्र उभयनिष्ठ अंक है, अतः U = 5।"},{"s":"General Intelligence and Reasoning","q":"Refer to the following number and symbol series and answer the question that follows. Counting to be done from left to right only. (Left) 3 4 7 # # # 5 * £ 8 2 £ & € 2 $ £ @ 3 # 7 & (Right) How many such symbols are there each of which is immediately preceded by a number and also immediately followed by a symbol?","o":["6","5","3","4"],"a":3,"e":"Symbols preceded by a number and followed by a symbol: 7#, 5*, 2£ and 2$. That makes 4.","qh":"निम्नलिखित संख्या और प्रतीक श्रृंखला का संदर्भ लीजिए तथा नीचे दिए गए प्रश्न का उत्तर दीजिए। गिनती केवल बाएं से दाएं की जानी है। (बाएं) 3 4 7 # # # 5 * £ 8 2 £ & € 2 $ £ @ 3 # 7 & (दाएं) ऐसे कितने प्रतीक हैं जिनमें से प्रत्येक के ठीक पहले एक संख्या और ठीक बाद एक प्रतीक है?","oh":["6","5","3","4"],"eh":"वे प्रतीक जिनसे पहले संख्या और बाद में प्रतीक है: 7#, 5*, 2£ और 2$। कुल 4।"},{"s":"General Intelligence and Reasoning","q":"If 2 is added to each even digit and 1 is subtracted from each odd digit in the number 91526374, what will be the sum of second digit from left and third digit from right in the new number thus formed?","o":["10","14","6","2"],"a":3,"e":"91526374 becomes 80448266. Second from the left is 0 and third from the right is 2, so 0 + 2 = 2.","qh":"यदि संख्या 91526374 में, प्रत्येक सम अंक में 2 जोड़ा जाए तथा प्रत्येक विषम अंक में से 1 घटाया जाए, तो इस प्रकार बनी नई संख्या में बाएं से दूसरे अंक तथा दाएं से तीसरे अंक का योग कितना होगा?","oh":["10","14","6","2"],"eh":"91526374, 80448266 बन जाता है। बाएँ से दूसरा 0 और दाएँ से तीसरा 2 है, अतः 0 + 2 = 2।"},{"s":"General Intelligence and Reasoning","q":"In the following triads, each group of letters is related to the subsequent one following a certain logic. Select from the given options, the one which follows the same logic. TOWN - NWTO - TWON CLAW - WACL - CALW","o":["PICK - KCPI - PCIK","ROSE - RSOE - ESOR","FUME - UMFE - UMEF","HALF - FLHA - ALHF"],"a":0,"e":"Pattern: letters 4-3-1-2, then the original's 1-3-2-4. PICK → KCPI → PCIK.","qh":"निम्नलिखित त्रिकों में, अक्षरों का प्रत्येक समूह एक निश्चित तर्क का अनुसरण करते हुए अगले समूह से संबंधित है। दिए गए विकल्पों में से उस विकल्प का चयन कीजिए जो समान तर्क का अनुसरण करता हो। TOWN - NWTO - TWON CLAW - WACL - CALW","oh":["PICK - KCPI - PCIK","ROSE - RSOE - ESOR","FUME - UMFE - UMEF","HALF - FLHA - ALHF"],"eh":"पैटर्न: अक्षर 4-3-1-2, फिर मूल शब्द के 1-3-2-4। PICK → KCPI → PCIK।"},{"s":"General Intelligence and Reasoning","q":"Seven boxes L, M, N, O, P, Q and R are kept one over the other but not necessarily in the same order. M is kept fourth from the bottom. O is placed immediately below M. Q is placed immediately above R. P is the topmost box. M is placed immediately below L. Which box is placed at the bottom?","o":["O","R","L","Q"],"a":1,"e":"Bottom to top: R, Q, O, M, L, N, P. R is at the bottom.","qh":"सात डिब्बे L, M, N, O, P, Q और R एक के ऊपर एक रखे गए हैं, लेकिन जरूरी नहीं कि इसी क्रम में रखे हों। M को नीचे से चौथे स्थान पर रखा गया है। O को M के ठीक नीचे रखा गया है। Q को R के ठीक ऊपर रखा गया है। P सबसे ऊपर वाला डिब्बा है। M को L के ठीक नीचे रखा गया है। सबसे नीचे कौन- सा डिब्बा रखा गया है?","oh":["O","R","L","Q"],"eh":"नीचे से ऊपर: R, Q, O, M, L, N, P। R सबसे नीचे है।"},{"s":"General Intelligence and Reasoning","q":"Rishabh starts from Point A and drives 9 km towards west. He then takes a left turn, drives 8 km, turns left and drives 15 km. He then takes a right turn and drives 6 km. He takes a final right turn, drives 6 km and stops at Point P. How far (shortest distance) and towards which direction should he drive in order to reach Point A again? (All turns are 90° turns only unless specified.)","o":["16 km towards east","14 km towards north","16 km towards west","14 km towards south"],"a":1,"e":"Net position: 14 km south of A (x: −9 + 15 − 6 = 0), so he drives 14 km north.","qh":"ऋषभ, बिंदु A से ड्राइव करना शुरू करता है और पश्चिम की ओर 9 km ड्राइव करता है। फिर वह बाएं मुड़ता है और 8 km ड्राइव करता है, फिर बाएं मुड़ता है और 15 km ड्राइव करता है। फिर वह दाएं मुड़ता है और 6 km ड्राइव करता है। वह अंत में दाएं मुड़ता है और 6 km ड्राइव करके बिंदु P पर रुक जाता है। बिंदु A पर वापस पहुँचने के लिए उसे कितनी दूर (न्यूनतम दूरी) और किस दिशा में ड्राइव करना चाहिए? (जब तक निर्दिष्ट न किया जाए, सभी मोड़ केवल 90° के मोड़ हैं।)","oh":["16 km, पूर्व की ओर","14 km, उत्तर की ओर","16 km, पश्चिम की ओर","14 km, दक्षिण की ओर"],"eh":"शुद्ध स्थिति: A से 14 km दक्षिण (x: −9 + 15 − 6 = 0), अतः वह 14 km उत्तर जाता है।"},{"s":"General Intelligence and Reasoning","q":"What should come in place of the question mark (?) in the given series? 85 86 88 92 100 ?","o":["118","117","116","115"],"a":2,"e":"Differences double: +1, +2, +4, +8, +16, so 100 + 16 = 116.","qh":"दी गई श्रृंखला में प्रश्न-चिह्न (?) के स्थान पर क्या आना चाहिए? 85 86 88 92 100 ?","oh":["118","117","116","115"],"eh":"अंतर दोगुने होते हैं: +1, +2, +4, +8, +16, अतः 100 + 16 = 116।"},{"s":"General Intelligence and Reasoning","q":"Mr. Into ranked 49th from the bottom and 56th from the top in his class. How many students are there in his class?","o":["105","103","104","107"],"a":2,"e":"Total = 49 + 56 − 1 = 104.","qh":"मिस्टर इंटू अपनी कक्षा में नीचे से 49वें स्थान पर और ऊपर से 56वें स्थान पर है। उसकी कक्षा में कुल कितने विद्यार्थी हैं?","oh":["105","103","104","107"],"eh":"कुल = 49 + 56 − 1 = 104।"},{"s":"General Intelligence and Reasoning","q":"Based on the English alphabetical order, three of the following four letter cluster pairs are alike in a certain way and thus form a group. Which is the one that DOES NOT belong to that group? (NOTE: The odd one out is not based on the number of consonants/vowels or their position in the letter cluster.)","o":["TM-WR","OH-RN","NG-QL","JC-MH"],"a":1,"e":"The others are +3, +5 (T→W, M→R). In OH-RN, H→N is +6.","qh":"अंग्रेजी वर्णमाला क्रम पर आधारित, निम्नलिखित चार अक्षर-समूह युग्मों में से तीन एक निश्चित तरीके से एकसमान हैं और इस प्रकार वे एक ग्रुप बनाते हैं। कौन-सा अक्षर-समूह युग्म उस ग्रुप से संबंधित नहीं है? (नोट: असंगत अक्षर-समूह युग्म, व्यंजनों/स्वरों की संख्या या उनकी स्थिति पर आधारित नहीं है।)","oh":["TM-WR","OH-RN","NG-QL","JC-MH"],"eh":"अन्य में +3, +5 है (T→W, M→R)। OH-RN में H→N, +6 है।"},{"s":"General Intelligence and Reasoning","q":"Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements. Statements: Some notes are books. All books are tables. Conclusion (I): Some notes are tables. Conclusions (II): All tables are books.","o":["Neither conclusion (I) nor (II) follows.","Only conclusion (II) follows.","Both conclusions (I) and (II) follow.","Only conclusion (I) follows."],"a":3,"e":"Some notes are books and all books are tables, so (I) follows. (II) doesn't.","qh":"दिए गए कथनों और निष्कर्षों का ध्यानपूर्वक अध्ययन कीजिए। यह मानते हुए कि कथनों में दी गई जानकारी सत्य है, भले ही वह सामान्यतः ज्ञात तथ्यों से भिन्न प्रतीत होती हो, तय कीजिए कि दिए गए निष्कर्षों में से कौन-से निष्कर्ष, कथनों का तार्किक रूप से अनुसरण करते हैं। कथन: कुछ नोट्स, किताबें हैं। सभी किताबें, टेबल हैं। निष्कर्ष (I): कुछ नोट्स, टेबल हैं। निष्कर्ष (II): सभी टेबल, किताबें हैं।","oh":["न तो निष्कर्ष (I) और न ही (II) अनुसरण करता है।","केवल निष्कर्ष (II) अनुसरण करता है।","निष्कर्ष (I) और (II) दोनों अनुसरण करते हैं।","केवल निष्कर्ष (I) अनुसरण करता है।"],"eh":"कुछ नोट किताबें हैं और सभी किताबें मेज़ हैं, अतः (I) अनुसरण करता है। (II) नहीं करता।"},{"s":"General Intelligence and Reasoning","q":"What should come in place of the question mark (?) in the given series? 3 12 30 57 93 ?","o":["130","138","135","140"],"a":1,"e":"Differences are multiples of 9: 9, 18, 27, 36, then 45. 93 + 45 = 138.","qh":"दी गई श्रृंखला में प्रश्न-चिन्ह (?) के स्थान पर क्या आएगा? 3 12 30 57 93 ?","oh":["130","138","135","140"],"eh":"अंतर 9 के गुणज हैं: 9, 18, 27, 36, फिर 45। 93 + 45 = 138।"}]});
